from pathlib import Path
import pandas as pd
import pytest

# Custom test assertion helper to compare Pandas DataFrames with numeric tolerance
from tests.helpers.compare import assert_tables_close

# Locate the root fixtures directory relative to this test file: ../../fixtures/exp49
FIXTURES_DIR = Path(__file__).resolve().parent.parent / "fixtures" / "exp49"
# Directory containing ground-truth/reference data generated by legacy scripts
REFERENCE_DIR = FIXTURES_DIR / "reference"

# Lab and reference fixtures are serialized in ASCII with 6 decimal places.
# The theoretical maximum truncation/rounding error introduced by this format
# is half a unit in the last decimal place (0.5 * 1e-6 = 5e-7).
# To prevent relative tolerances from allowing loose bounds on large physical quantities,
# rtol is set to 0 and atol is strictly calibrated to 5e-7 plus
# a minimal float precision slack (1e-9).
RTOL_LEGACY = 0.0
ATOL_LEGACY = 5e-7 + 1e-9


def _load_fixture_table(base_path: Path, columns: list[str]) -> pd.DataFrame:
    """
    Load legacy whitespace-separated fixture tables
    Supports both uncompressed (.txt) and gzip-compressed (.txt.gz) variants
    """
    gz_path = base_path.with_name(f"{base_path.name}.txt.gz")
    txt_path = base_path.with_name(f"{base_path.name}.txt")
    
    # Prefer .txt.gz if present to save disk space; fallback to .txt
    target_path = gz_path if gz_path.exists() else txt_path

    if not target_path.exists():
        raise FileNotFoundError(f"Fixture not found: neither {gz_path} nor {txt_path} exist.")

    # Legacy routines format tables with variable whitespace separators (spaces/tabs)
    df = pd.read_csv(target_path, sep=r"\s+", engine="python")
    
    # Overwrite column headers to match the pipeline's output schema
    if columns:
        df.columns = columns
    return df


@pytest.fixture(scope="module")
def exp49_analysis_results(exp49_outputs):
    """
    Core analysis of experiment 49, shared with the whole test session (see conftest.py).

    It uses the lab parameters of app/resources, the same ones the legacy reference was
    produced with: radial_map=False, dt=0.1, tumbling_threshold=5.0, disc_radius=350,
    and all trajectory filters at their neutral values.
    """
    return exp49_outputs


# Regression test cases
# Compares each computed DataFrame against reference data within legacy tolerance

def test_regression_theta(exp49_analysis_results):
    # Verify radialized orientation angle (theta) vs distance from center
    expected = _load_fixture_table(FIXTURES_DIR / "Theta_exp49_FluoRadialised", ["theta", "dist"])
    assert_tables_close(exp49_analysis_results.theta, expected, rtol=RTOL_LEGACY, atol=ATOL_LEGACY)


def test_regression_angle(exp49_analysis_results):
    # Verify instantaneous trajectory angles, radial distance, and swimming velocity.
    expected = _load_fixture_table(FIXTURES_DIR / "angle_exp49", ["angle", "dist", "v"])
    assert_tables_close(exp49_analysis_results.angle, expected, rtol=RTOL_LEGACY, atol=ATOL_LEGACY)


